local config = {
  str_homestory_N21yongchi_90020101_1_dialog_content = "Nossa, está tão quente...",
  str_homestory_N21yongchi_90020101_2_dialog_content = "Sim, eu sinto que o clima tem estado muito mais quente ultimamente.",
  str_homestory_N21yongchi_90020101_3_dialog_content = "Até as plantas em Cloud Gardens parecem estar fartas do sol.",
  str_homestory_N21yongchi_90020101_4_dialog_content = "Estou começando a sentir falta de Harbour City.",
  str_homestory_N21yongchi_90020101_5_dialog_content = "A brisa, o mar no verão...",
  str_homestory_N21yongchi_90020101_6_dialog_content = "Ah, e poder ir nadar juntos...",
  str_homestory_N21yongchi_90020101_7_dialog_content = "Sim, não há lugar para nadar em Cloud Gardens.",
  str_homestory_N21yongchi_90020101_8_dialog_content = "Então, talvez devêssemos fazer isso em algum lugar?",
  str_homestory_N21yongchi_90020101_9_dialog_content = "Acho que as pessoas podem gostar disso.",
  str_homestory_N21yongchi_90020101_10_dialog_content = "Boa ideia!",
  str_homestory_N21yongchi_90020101_11_dialog_content = "Já construímos muitos prédios. Por que não ter um Parque Aquático Cloud Gardens?",
  str_homestory_N21yongchi_90020101_12_dialog_content = "Parece que você tem um plano.",
  str_homestory_N21yongchi_90020101_13_dialog_content = "Ainda não. Mas eu definitivamente quero um parque aquático.",
  str_homestory_N21yongchi_90020101_14_dialog_content = "Vamos precisar de muita água. E um lugar para colocar a água.",
  str_homestory_N21yongchi_90020101_15_dialog_content = "Vamos começar cavando uma piscina.",
  str_homestory_N21yongchi_90020101_16_dialog_content = "Uma piscina grande o suficiente para conter muitos aurorianos significará muito trabalho de espada.",
  str_homestory_N21yongchi_90020101_17_dialog_content = "Deve haver um auroriano que seja bom em escavação e construção. Deixe-me pensar...",
  str_homestory_N21yongchi_90020101_18_dialog_content = "Isso me lembra, Ciel é a pessoa que você precisa. Ela tem muita experiência com esse tipo de trabalho.",
  str_homestory_N21yongchi_90020101_19_dialog_content = "Ciel? Entendi!",
  str_homestory_N21yongchi_90020101_20_dialog_content = "Eu vou falar com ela.",
  str_homestory_N21yongchi_90020102_1_dialog_content = "Ciel!",
  str_homestory_N21yongchi_90020102_2_dialog_content = "Ah! Ah é você, PlayerName.",
  str_homestory_N21yongchi_90020102_3_dialog_content = "Desculpe, eu te dei um susto?",
  str_homestory_N21yongchi_90020102_4_dialog_content = "Não. Eu estava apenas me concentrando em fazer alguns ajustes no Styx.",
  str_homestory_N21yongchi_90020102_5_dialog_content = "Há algo de errado com isso?",
  str_homestory_N21yongchi_90020102_6_dialog_content = "Espero que não esteja com defeito.",
  str_homestory_N21yongchi_90020102_7_dialog_content = "Não, nada disso...",
  str_homestory_N21yongchi_90020102_8_dialog_content = "Eu tive uma ideia para alguns ajustes ligeiramente radicais.",
  str_homestory_N21yongchi_90020102_9_dialog_content = "PlayerName, você sabe que muitas vezes ajudo o oficial Charon a cavar túneis, não sabe?",
  str_homestory_N21yongchi_90020102_10_dialog_content = "Se essas mudanças funcionarem, posso dobrar a velocidade de escavação do Styx.",
  str_homestory_N21yongchi_90020102_11_dialog_content = "Uau, isso é incrível!",
  str_homestory_N21yongchi_90020102_12_dialog_content = "O problema é que o desempenho da duração caiu 90%...",
  str_homestory_N21yongchi_90020102_13_dialog_content = "Isso é... menos incrível.",
  str_homestory_N21yongchi_90020102_14_dialog_content = "Sim, então eu preciso continuar trabalhando nisso e ver se consigo encontrar uma correção.",
  str_homestory_N21yongchi_90020102_15_dialog_content = "Entendi.",
  str_homestory_N21yongchi_90020102_16_dialog_content = "Bem, se houver algo que eu possa fazer para ajudar, é só me avisar.",
  str_homestory_N21yongchi_90020102_17_dialog_content = "Ah, é mesmo?",
  str_homestory_N21yongchi_90020102_18_dialog_content = "Na verdade... há algo que você poderia fazer por mim, PlayerName.",
  str_homestory_N21yongchi_90020102_19_dialog_content = "Claro. Diga!",
  str_homestory_N21yongchi_90020102_20_dialog_content = "Você poderia me trazer um pouco de minério?",
  str_homestory_N21yongchi_90020102_21_dialog_content = "Preciso dele para testar o Styx.",
  str_homestory_N21yongchi_90020102_22_dialog_content = "Não é um problema. Deixe isso comigo.",
  str_homestory_N21yongchi_90020103_1_dialog_content = "Você conseguiu o minério que eu preciso?",
  str_homestory_N21yongchi_90020103_2_dialog_content = "Claro que sim! ({1}/{2})",
  str_homestory_N21yongchi_90020103_3_dialog_content = "Obrigado! Eu sabia que podia confiar em você, PlayerName.",
  str_homestory_N21yongchi_90020103_4_dialog_content = "E você foi tão rápido também.",
  str_homestory_N21yongchi_90020103_5_dialog_content = "Heheh. Acho que todo o trabalho que venho fazendo aqui em Cloud Gardens está me fortalecendo.",
  str_homestory_N21yongchi_90020103_6_dialog_content = "Trabalhos como esse parecem superfáceis agora.",
  str_homestory_N21yongchi_90020103_7_dialog_content = "E como acontece, eu tenho um favor a lhe pedir também.",
  str_homestory_N21yongchi_90020103_8_dialog_content = "Sim, eu sei. A piscina, certo?",
  str_homestory_N21yongchi_90020103_9_dialog_content = "Huh? Como você sabia disso, Ciel?",
  str_homestory_N21yongchi_90020103_10_dialog_content = "A senhorita Carleen veio me ver enquanto você estava recolhendo o minério.",
  str_homestory_N21yongchi_90020103_11_dialog_content = "Deixe para mim. Tudo o que você precisa fazer é marcar a área onde deseja construir a piscina.",
  str_homestory_N21yongchi_90020103_12_dialog_content = "Eu irei ajudar quando terminar com Styx.",
  str_homestory_N21yongchi_90020103_13_dialog_content = "OK. Muito obrigado.",
  str_homestory_N21yongchi_90020103_14_dialog_content = "Não o suficiente.",
  str_homestory_N21yongchi_90020103_15_dialog_content = "Bem, estou contando com você.",
  str_homestory_N21yongchi_90020104_1_dialog_content = "Huff, puff... Isso deve dizer a Ciel onde eu quero a piscina.",
  str_homestory_N21yongchi_90020104_2_dialog_content = "Não estou acostumado a cavar assim. É um trabalho duro.",
  str_homestory_N21yongchi_90020104_3_dialog_content = "Não consigo nem imaginar ter que cavar uma piscina inteira sozinho.",
  str_homestory_N21yongchi_90020104_4_dialog_content = "Mas isso deve ser suficiente. Agora tudo o que tenho a fazer é esperar por Ciel.",
  str_homestory_N21yongchi_90020104_5_dialog_content = "E feito!",
  str_homestory_N21yongchi_90020104_6_dialog_content = "Uau! Isso é inacreditavel.",
  str_homestory_N21yongchi_90020104_7_dialog_content = "Ciel, você é incrível!",
  str_homestory_N21yongchi_90020104_8_dialog_content = "Bem, não era só eu. Eu não poderia ter feito isso sem Styx.",
  str_homestory_N21yongchi_90020104_9_dialog_content = "E Miss Carleen deu-me muitos conselhos.",
  str_homestory_N21yongchi_90020104_10_dialog_content = "Mas ainda não parece perfeito.",
  str_homestory_N21yongchi_90020104_11_dialog_content = "Você pode precisar fazer algum polimento, PlayerName.",
  str_homestory_N21yongchi_90020104_12_dialog_content = "Já acho incrível. E muito melhor do que eu e minha pá poderíamos ter feito.",
  str_homestory_N21yongchi_90020104_13_dialog_content = "Deixe a limpeza comigo, Ciel.",
  str_homestory_N21yongchi_90020105_1_dialog_content = "Sim! Limpei a piscina e agora as pessoas podem usá-la.",
  str_homestory_N21yongchi_90020105_2_dialog_content = "Vou contar a Carleen.",
  str_homestory_N21yongchi_90020106_1_dialog_content = "Carleen!",
  str_homestory_N21yongchi_90020106_2_dialog_content = "PlayerName, você voltou.",
  str_homestory_N21yongchi_90020106_3_dialog_content = "Você conseguiu o minério para Ciel?",
  str_homestory_N21yongchi_90020106_4_dialog_content = "Sim eu fiz. E a piscina foi construída!",
  str_homestory_N21yongchi_90020106_5_dialog_content = "Eu não sabia que você ia falar com Ciel também.",
  str_homestory_N21yongchi_90020106_6_dialog_content = "Sim, de repente pensei em algumas ideias que podem ajudar.",
  str_homestory_N21yongchi_90020106_7_dialog_content = "Então eu fui vê-la e passei.",
  str_homestory_N21yongchi_90020106_8_dialog_content = "Não pensei que a piscina fosse tão rápida de construir.",
  str_homestory_N21yongchi_90020106_9_dialog_content = "Bem, ainda é meio básico. É apenas a piscina e nada mais.",
  str_homestory_N21yongchi_90020106_10_dialog_content = "Posso ajudar com isso.",
  str_homestory_N21yongchi_90020106_11_dialog_content = "Afinal, você tem trabalhado tanto para nos receber.",
  str_homestory_N21yongchi_90020106_12_dialog_content = "Não podemos confiar em você para fazer tudo.",
  str_homestory_N21yongchi_90020106_13_dialog_content = "É educado que nós, hóspedes, também o ajudemos.",
  str_homestory_N21yongchi_90020106_14_dialog_content = "Obrigada, Carleen.",
  str_homestory_N21yongchi_90020106_15_dialog_content = "Embora eu nunca tenha pensado em vocês como convidados.",
  str_homestory_N21yongchi_90020106_16_dialog_content = "Você está aqui em Cloud Gardens, e isso faz de você uma família.",
  str_homestory_N21yongchi_90020106_17_dialog_content = "E o Cloud Gardens Water Park estará aberto a qualquer auroriano que queira visitar.",
  str_homestory_N21yongchi_90020106_18_dialog_content = "Parece bom!",
  str_homestory_N21yongchi_90020201_1_dialog_content = "PlayerName!",
  str_homestory_N21yongchi_90020201_2_dialog_content = "Oi, Vice.",
  str_homestory_N21yongchi_90020201_3_dialog_content = "Passei por uma bela piscina no caminho para cá. Você o construiu?",
  str_homestory_N21yongchi_90020201_4_dialog_content = "Não estava aqui há alguns dias, estava?",
  str_homestory_N21yongchi_90020201_5_dialog_content = "Não. Carleen veio com o projeto, então Ciel fez o trabalho de construção.",
  str_homestory_N21yongchi_90020201_6_dialog_content = "Acho legal também!",
  str_homestory_N21yongchi_90020201_7_dialog_content = "Ah, eu deveria ter imaginado que Carleen contribuiu. Há um sabor definitivo de Lumopolis aqui.",
  str_homestory_N21yongchi_90020201_8_dialog_content = "E é bom saber que Ciel está encontrando um uso para todas as habilidades de construção de túneis que ela acumulou.",
  str_homestory_N21yongchi_90020201_9_dialog_content = "Exatamente! A piscina não seria tão grande se não fosse por sua ajuda.",
  str_homestory_N21yongchi_90020201_10_dialog_content = "Mas não vai ser só uma piscina. Estou planejando um parque aquático para que todos possam nadar e se divertir!",
  str_homestory_N21yongchi_90020201_11_dialog_content = "Isso soa como você, PlayerName.",
  str_homestory_N21yongchi_90020201_12_dialog_content = "E você me deixou todo empolgado agora. Como posso ajudar?",
  str_homestory_N21yongchi_90020201_13_dialog_content = "(Eu tenho um mau pressentimento sobre isso.)",
  str_homestory_N21yongchi_90020201_14_dialog_content = "(Quando Vice diz ajuda, ela quer dizer com... sua comida?)",
  str_homestory_N21yongchi_90020201_15_dialog_content = "Eu sei!",
  str_homestory_N21yongchi_90020201_16_dialog_content = "Oh? O-o quê?",
  str_homestory_N21yongchi_90020201_17_dialog_content = "Lembro-me de aprender a nadar em Illumina.",
  str_homestory_N21yongchi_90020201_18_dialog_content = "O treinador nos deu alguns equipamentos de segurança para ajudar.",
  str_homestory_N21yongchi_90020201_19_dialog_content = "Como bolas infláveis e coletes salva-vidas.",
  str_homestory_N21yongchi_90020201_20_dialog_content = "Assim poderíamos praticar natação com mais segurança.",
  str_homestory_N21yongchi_90020201_21_dialog_content = "E os aurorianos que não tinham nadado antes podiam se acostumar a estar na água.",
  str_homestory_N21yongchi_90020201_22_dialog_content = "Entendi.",
  str_homestory_N21yongchi_90020201_23_dialog_content = "Eu acho que é um pouco perigoso apenas encher a piscina com água. . .",
  str_homestory_N21yongchi_90020201_24_dialog_content = "Boa reflexão, Vice!",
  str_homestory_N21yongchi_90020201_25_dialog_content = "Heheh. A segurança deve estar sempre em primeiro lugar.",
  str_homestory_N21yongchi_90020201_26_dialog_content = "Deixe-me pensar, onde poderíamos conseguir esse tipo de equipamento...",
  str_homestory_N21yongchi_90020201_27_dialog_content = "Parece que me lembro da última vez que fui surfar...",
  str_homestory_N21yongchi_90020201_28_dialog_content = "Eu sei! O circo terá alguns.",
  str_homestory_N21yongchi_90020201_29_dialog_content = "Eu deveria ir e perguntar a Rainbow.",
  str_homestory_N21yongchi_90020201_30_dialog_content = "Mantenha o bom trabalho! Eu espero aqui por você.",
  str_homestory_N21yongchi_90020202_1_dialog_content = "Isso é PlayerName! Olá.",
  str_homestory_N21yongchi_90020202_2_dialog_content = "Você parece estar de bom humor. O que está acontecendo?",
  str_homestory_N21yongchi_90020202_3_dialog_content = "Bem, Cloud Gardens é minha casa. Estou feliz por estar de volta aqui.",
  str_homestory_N21yongchi_90020202_4_dialog_content = "E você, Rainbow? Você está se acomodando?",
  str_homestory_N21yongchi_90020202_5_dialog_content = "Eu acho que sim. Afinal, tive muitas aventuras a bordo do Emerald.",
  str_homestory_N21yongchi_90020202_6_dialog_content = "Se alguma coisa, eu suspeito que a vida em terra firme é um pouco... excessivamente estável.",
  str_homestory_N21yongchi_90020202_7_dialog_content = "Então, PlayerName, por que o súbito interesse em mim?",
  str_homestory_N21yongchi_90020202_8_dialog_content = "Eu vi você vindo direto para mim a milhas de distância. Você precisava de algo?",
  str_homestory_N21yongchi_90020202_9_dialog_content = "Haha, você viu através de mim.",
  str_homestory_N21yongchi_90020202_10_dialog_content = "É assim: construí uma piscina em Cloud Gardens e quero transformá-la em um parque aquático.",
  str_homestory_N21yongchi_90020202_11_dialog_content = "Mas há muitos aurorianos aqui que não sabem nadar.",
  str_homestory_N21yongchi_90020202_12_dialog_content = "Então eu queria perguntar se há anéis de natação sobressalentes a bordo do Emerald.",
  str_homestory_N21yongchi_90020202_13_dialog_content = "Ah. Bem, você veio para a pessoa certa. Sou responsável pelas lojas de equipamentos de segurança.",
  str_homestory_N21yongchi_90020202_14_dialog_content = "Aposto que você não esperava isso.",
  str_homestory_N21yongchi_90020202_15_dialog_content = "Haha! Bem, considerando quantos empregos você já tem, Rainbow, acho que não deveria me surpreender ao descobrir que você ainda tem mais um.",
  str_homestory_N21yongchi_90020202_16_dialog_content = "Então, você poderia me emprestar um pouco? Ou eu poderia comprá-los de você?",
  str_homestory_N21yongchi_90020202_17_dialog_content = "Bem... acho que năo posso. Não são meus, pertencem à Esmeralda. Eu apenas cuido deles.",
  str_homestory_N21yongchi_90020202_18_dialog_content = "Embora se você pudesse me fazer um pequeno favor, PlayerName...",
  str_homestory_N21yongchi_90020202_19_dialog_content = "Nada. Basta nomeá-lo.",
  str_homestory_N21yongchi_90020202_20_dialog_content = "Heheh, você com certeza é fácil de lidar, PlayerName.",
  str_homestory_N21yongchi_90020202_21_dialog_content = "Nosso mestre de cerimônias, Jeno, adora criar peixes. Ele é fascinado por todas as diferentes espécies aqui em Cloud Gardens.",
  str_homestory_N21yongchi_90020202_22_dialog_content = "Talvez você possa pegar alguns para ele? Se você fizer isso, tenho certeza que posso convencê-lo a lhe dar alguns anéis de natação.",
  str_homestory_N21yongchi_90020202_23_dialog_content = "Entendi. E eu sou um pescador campeão.",
  str_homestory_N21yongchi_90020202_24_dialog_content = "Espere aí. Estarei de volta em duas sacudidas de rabo de peixe.",
  str_homestory_N21yongchi_90020203_1_dialog_content = "Você pegou o peixe?",
  str_homestory_N21yongchi_90020203_2_dialog_content = "Claro que sim!({1}/{2})",
  str_homestory_N21yongchi_90020203_3_dialog_content = "Uau, você pegou tantos. Deixe-me dar uma olhada.",
  str_homestory_N21yongchi_90020203_4_dialog_content = "Hmm, este é o mais bonito. Parece o tipo que Jeno gostaria.",
  str_homestory_N21yongchi_90020203_5_dialog_content = "Deixei os anéis de natação que você queria na sua piscina.",
  str_homestory_N21yongchi_90020203_6_dialog_content = "E ele também lhe deu um vestiário que costumávamos usar durante as competições. É meio básico.",
  str_homestory_N21yongchi_90020203_7_dialog_content = "Mas dará aos visitantes um lugar para se trocar e tomar banho.",
  str_homestory_N21yongchi_90020203_8_dialog_content = "Muito obrigado, Rainbow!",
  str_homestory_N21yongchi_90020203_9_dialog_content = "Não mencione isso, PlayerName. Embora, se você não estiver ocupado, talvez possa buscar um pouco de água para manter esses peixes?",
  str_homestory_N21yongchi_90020203_10_dialog_content = "Eu não acho que eles têm espaço suficiente agora. Quero colocá-los em um recipiente maior antes de levá-los para Jeno.",
  str_homestory_N21yongchi_90020203_11_dialog_content = "Sem problemas. Eu volto já!",
  str_homestory_N21yongchi_90020203_12_dialog_content = "I'm working on it!",
  str_homestory_N21yongchi_90020203_13_dialog_content = "Faça o seu melhor!",
  str_homestory_N21yongchi_90020204_1_dialog_content = "Entendeu?",
  str_homestory_N21yongchi_90020204_2_dialog_content = "Eu fiz!",
  str_homestory_N21yongchi_90020204_3_dialog_content = "Isso foi rápido. Ok, obrigado.",
  str_homestory_N21yongchi_90020204_4_dialog_content = "E eu vou levar esses peixes também.",
  str_homestory_N21yongchi_90020204_5_dialog_content = "Claro!",
  str_homestory_N21yongchi_90020204_6_dialog_content = "A caminho.",
  str_homestory_N21yongchi_90020204_7_dialog_content = "Um pouco de água vai fazer isso, obrigado.",
  str_homestory_N21yongchi_90020205_1_dialog_content = "Ok, isso deve funcionar.",
  str_homestory_N21yongchi_90020205_2_dialog_content = "E vou colocar as bolas infláveis por perto.",
  str_homestory_N21yongchi_90020301_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020301_2_dialog_content = "Ei, mestre de cerimônias Jeno!",
  str_homestory_N21yongchi_90020301_3_dialog_content = "Eu só estava pensando em você! Quero perguntar sobre o novo parque aquático: como você acha que podemos garantir que seja um sucesso?",
  str_homestory_N21yongchi_90020301_4_dialog_content = "Parque aquático?",
  str_homestory_N21yongchi_90020301_5_dialog_content = "Ah sim, Ciel mencionou isso.",
  str_homestory_N21yongchi_90020301_6_dialog_content = "Sinceramente, acho que já está ótimo.",
  str_homestory_N21yongchi_90020301_7_dialog_content = "Mas...",
  str_homestory_N21yongchi_90020301_8_dialog_content = "Mas?",
  str_homestory_N21yongchi_90020301_9_dialog_content = "Está faltando alguma coisa. Uma coisa muito importante.",
  str_homestory_N21yongchi_90020301_10_dialog_content = "Pense de volta. Qual é a sua memória de verão mais clara?",
  str_homestory_N21yongchi_90020301_11_option_content = "Picadas de mosquito.",
  str_homestory_N21yongchi_90020301_12_dialog_content = "Isso não. Quero dizer uma boa memória.",
  str_homestory_N21yongchi_90020301_13_option_content = "Ah. Uma bebida gelada?",
  str_homestory_N21yongchi_90020301_14_dialog_content = "Perto, mas não.",
  str_homestory_N21yongchi_90020301_15_dialog_content = "Ok, eu só vou te dizer.",
  str_homestory_N21yongchi_90020301_16_dialog_content = "O que seu parque aquático precisa é... sorvete.",
  str_homestory_N21yongchi_90020301_17_dialog_content = "Leite e açúcar são perfeitamente combinados em temperaturas abaixo de zero.",
  str_homestory_N21yongchi_90020301_18_dialog_content = "Batendo sua língua como fogos de artifício congelados no calor escaldante do verão.",
  str_homestory_N21yongchi_90020301_19_dialog_content = "Não estou interessado em alimentos açucarados. Eles fazem as pessoas ganhar peso. Mas não posso negar que sorvete também faz as pessoas felizes.",
  str_homestory_N21yongchi_90020301_20_dialog_content = "Sim!",
  str_homestory_N21yongchi_90020301_21_dialog_content = "Sorvete, hmm... Vou falar com a Vice, ela fez raspadinha no ano passado!",
  str_homestory_N21yongchi_90020301_22_dialog_content = "Obrigado, Jeno!",
  str_homestory_N21yongchi_90020301_23_dialog_content = "Partindo tão cedo?",
  str_homestory_N21yongchi_90020301_24_dialog_content = "Que pressa.",
  str_homestory_N21yongchi_90020302_1_dialog_content = "Vice!",
  str_homestory_N21yongchi_90020302_2_dialog_content = "Huh? E aí, PlayerName? Você está sem fôlego.",
  str_homestory_N21yongchi_90020302_3_dialog_content = "Eu sei como podemos atrair mais pessoas para o Cloud Gardens Water Park!",
  str_homestory_N21yongchi_90020302_4_dialog_content = "Oh? Bem, não me deixe em suspense.",
  str_homestory_N21yongchi_90020302_5_dialog_content = "Lembra-se do ano passado quando fizemos gelo raspado?",
  str_homestory_N21yongchi_90020302_6_dialog_content = "O que, gelo raspado de novo?",
  str_homestory_N21yongchi_90020302_7_dialog_content = "Para ser honesto, eu meio que perdi o interesse em sorvetes raspados.",
  str_homestory_N21yongchi_90020302_8_dialog_content = "Porque minhas conversas com Kleken sobre uma franquia de gelo raspado fracassaram, lembra?",
  str_homestory_N21yongchi_90020302_9_dialog_content = "Não é gelo raspado!",
  str_homestory_N21yongchi_90020302_10_dialog_content = "Desta vez vamos fazer sorvete!",
  str_homestory_N21yongchi_90020302_11_dialog_content = "Entendo...",
  str_homestory_N21yongchi_90020302_12_dialog_content = "Os sorvetes raspados são principalmente água, então o sabor é sempre um pouco maçante.",
  str_homestory_N21yongchi_90020302_13_dialog_content = "Mas se adicionarmos leite e frutas, ou mesmo carne... Podemos criar milhões de tipos diferentes!",
  str_homestory_N21yongchi_90020302_14_dialog_content = "É... carne?",
  str_homestory_N21yongchi_90020302_15_dialog_content = "Você está certo, eu nunca deveria ter me limitado ao gelo raspado. E posso adicionar uma nova dimensão a tantos alimentos diferentes congelando-os!",
  str_homestory_N21yongchi_90020302_16_dialog_content = "Hã?",
  str_homestory_N21yongchi_90020302_17_dialog_content = "Obrigado! Você é uma verdadeira inspiração.",
  str_homestory_N21yongchi_90020302_18_dialog_content = "Trarei algumas amostras. PlayerName, encontre algumas pessoas para prová-los.",
  str_homestory_N21yongchi_90020302_19_dialog_content = "Ou talvez você prefira provar minhas invenções você mesmo, PlayerName.",
  str_homestory_N21yongchi_90020302_20_dialog_content = "Ficarei encarregado de recrutar testadores. Você começa a trabalhar!",
  str_homestory_N21yongchi_90020303_1_dialog_content = "Hum. A quem devo perguntar?",
  str_homestory_N21yongchi_90020303_2_dialog_content = "Por que, se não é PlayerName!",
  str_homestory_N21yongchi_90020303_3_dialog_content = "Sobre o que você está tão pensando?",
  str_homestory_N21yongchi_90020303_4_dialog_content = "Oh! Brock.",
  str_homestory_N21yongchi_90020303_5_dialog_content = "(Lembro que Brock pode até beber bebidas de proteína de ovo de verme da areia.)",
  str_homestory_N21yongchi_90020303_6_dialog_content = "(Brock, meu amigo, peço desculpas pelo que estou prestes a infligir a você.)",
  str_homestory_N21yongchi_90020303_7_dialog_content = "Ei, por que você está encharcado de suor?",
  str_homestory_N21yongchi_90020303_8_dialog_content = "Este? Bem, acabei de fazer 100 flexões, 100 abdominais e 100 agachamentos.",
  str_homestory_N21yongchi_90020303_9_dialog_content = "Isso me aqueceu. Depois corri 10 quilômetros.",
  str_homestory_N21yongchi_90020303_10_dialog_content = "É a rotina favorita dos membros da Rediesel Wrench em seus dias de folga.",
  str_homestory_N21yongchi_90020303_11_dialog_content = "Isso é um dia de folga? De qualquer forma, você deve estar com calor depois de todo esse exercício.",
  str_homestory_N21yongchi_90020303_12_dialog_content = "Que tal experimentar um novo sabor de sorvete?",
  str_homestory_N21yongchi_90020303_13_dialog_content = "Isso ajudará a reabastecer sua energia e torná-lo ainda mais forte.",
  str_homestory_N21yongchi_90020303_14_dialog_content = "Parece inteligente!",
  str_homestory_N21yongchi_90020303_15_dialog_content = "Eu sabia que você me apoiava mais do que Sinsa!",
  str_homestory_N21yongchi_90020303_16_dialog_content = "Venha, então. Cadê esse sorvete delicioso?",
  str_homestory_N21yongchi_90020303_17_dialog_content = "Aqui, experimente!",
  str_homestory_N21yongchi_90020303_18_dialog_content = "Lambe Lambe.",
  str_homestory_N21yongchi_90020303_19_dialog_content = "Sorver sorver.",
  str_homestory_N21yongchi_90020303_20_dialog_content = "<color=#e8d9bb>Cabuum!</color>",
  str_homestory_N21yongchi_90020303_21_dialog_content = "Uau!!",
  str_homestory_N21yongchi_90020303_22_dialog_content = "Qual é a história desse sorvete?",
  str_homestory_N21yongchi_90020303_23_dialog_content = "Quando engoli, senti como se alguém tivesse me dado um soco no estômago.",
  str_homestory_N21yongchi_90020303_24_dialog_content = "Isso é um truque sorrateiro. Ainda mais sorrateiro do que Sinsa.",
  str_homestory_N21yongchi_90020303_25_dialog_content = "E-espere um minuto. Deixe-me pensar em um... quero dizer, explicar!",
  str_homestory_N21yongchi_90020303_26_dialog_content = "Eu sei! Talvez... seja uma forma de treinar para levar um soco?",
  str_homestory_N21yongchi_90020303_27_dialog_content = "Quer dizer, você vai precisar de mais do que músculos para vencer Sinsa, certo?",
  str_homestory_N21yongchi_90020303_28_dialog_content = "Você precisa ser capaz de continuar lutando, mesmo depois de levar um golpe, se quiser rir por último.",
  str_homestory_N21yongchi_90020303_29_dialog_content = "...",
  str_homestory_N21yongchi_90020303_30_dialog_content = "...",
  str_homestory_N21yongchi_90020303_31_dialog_content = "Você é um génio!",
  str_homestory_N21yongchi_90020303_32_dialog_content = "Existe mais? Posso ter alguns?",
  str_homestory_N21yongchi_90020304_1_dialog_content = "O mestre de cerimônias Jeno.",
  str_homestory_N21yongchi_90020304_2_dialog_content = "olá PlayerName.",
  str_homestory_N21yongchi_90020304_3_dialog_content = "Você já fez um sorvete? Eu deveria saber que você faria.",
  str_homestory_N21yongchi_90020304_4_dialog_content = "Bem, isso é apenas uma amostra.",
  str_homestory_N21yongchi_90020304_5_dialog_content = "Mas ouvi dizer que você é um verdadeiro gourmet, então...",
  str_homestory_N21yongchi_90020304_6_dialog_content = "Eu sei. Você quer que eu experimente, não é?",
  str_homestory_N21yongchi_90020304_7_dialog_content = "Não estou interessado em alimentos açucarados. Mas foi ideia minha, afinal.",
  str_homestory_N21yongchi_90020304_8_dialog_content = "Deixe-me provar.",
  str_homestory_N21yongchi_90020304_9_dialog_content = "Sorver sorver.",
  str_homestory_N21yongchi_90020304_10_dialog_content = "O-o que é isso?",
  str_homestory_N21yongchi_90020304_11_dialog_content = "Isso não é fogos de artifício congelados. Este é um trovão dentro da minha cabeça.",
  str_homestory_N21yongchi_90020304_12_dialog_content = "É tão... tabu. Um sabor proibido.",
  str_homestory_N21yongchi_90020304_13_dialog_content = "Mas tão encantador.",
  str_homestory_N21yongchi_90020304_14_dialog_content = "...",
  str_homestory_N21yongchi_90020304_15_dialog_content = "Jeno, você está bem?",
  str_homestory_N21yongchi_90020304_16_dialog_content = "Pegue isso, PlayerName.",
  str_homestory_N21yongchi_90020304_17_dialog_content = "O que é isso?",
  str_homestory_N21yongchi_90020304_18_dialog_content = "Uma máquina de sorvete.",
  str_homestory_N21yongchi_90020304_19_dialog_content = "Meu antecessor me disse uma vez—",
  str_homestory_N21yongchi_90020304_20_dialog_content = "Se você encontrar alguém cujo sorvete faça seu paladar vibrar, dê este presente a ele.",
  str_homestory_N21yongchi_90020304_21_dialog_content = "Esta máquina de sorvete está com a Esmeralda há muitos anos. Espero que lhe sirva bem.",
  str_homestory_N21yongchi_90020304_22_dialog_content = "E que você use para levar esse sabor a muito mais bocas.",
  str_homestory_N21yongchi_90020304_23_dialog_content = "Boo-hoo... Estou emocionado.",
  str_homestory_N21yongchi_90020304_24_dialog_content = "Obrigado, Jeno!",
  str_homestory_N21yongchi_90020305_1_dialog_content = "Vice, estou de volta!",
  str_homestory_N21yongchi_90020305_2_dialog_content = "Excelente, PlayerName.",
  str_homestory_N21yongchi_90020305_3_dialog_content = "O que todos acharam do meu sorvete?",
  str_homestory_N21yongchi_90020305_4_dialog_content = "Nós iremos! Brock avaliou muito bem.",
  str_homestory_N21yongchi_90020305_5_dialog_content = "Ele disse que seria de grande ajuda em sua rotina de treinamento físico.",
  str_homestory_N21yongchi_90020305_6_dialog_content = "Hum. Eu não sabia que ele era um homem de tão bom gosto.",
  str_homestory_N21yongchi_90020305_7_dialog_content = "Na verdade, adicionei uma lata de uma nova carne enlatada nutritiva da Illumina à mistura.",
  str_homestory_N21yongchi_90020305_8_dialog_content = "Então, por que você tem que adicionar carne ao sorvete...",
  str_homestory_N21yongchi_90020305_9_dialog_content = "Oh. Quaisquer outros comentários?",
  str_homestory_N21yongchi_90020305_10_dialog_content = "Sim! Jeno disse que estava delicioso.",
  str_homestory_N21yongchi_90020305_11_dialog_content = "E ele até nos deu essa máquina de sorvete.",
  str_homestory_N21yongchi_90020305_12_dialog_content = "Incrível! Isso significa que todos vão gostar do meu novo sorvete.",
  str_homestory_N21yongchi_90020305_13_dialog_content = "E com esta máquina para ajudar, será ainda mais fácil fazê-los.",
  str_homestory_N21yongchi_90020305_14_dialog_content = "Seremos tão eficientes quanto uma fábrica de conservas de carne.",
  str_homestory_N21yongchi_90020305_15_dialog_content = "Comparação estranha, mas tudo bem...",
  str_homestory_N21yongchi_90020305_16_dialog_content = "Devo experimentá-los também, antes de oferecê-los ao público...",
  str_homestory_N21yongchi_90020306_1_dialog_content = "Ok, está tudo esclarecido.",
  str_homestory_N21yongchi_90020306_2_dialog_content = "Agora todos podem saborear o sorvete do Vice.",
  str_homestory_N21yongchi_90020306_3_dialog_content = "Hum. Devo tentar um, ou não?",
  str_homestory_N21yongchi_90020306_4_dialog_content = "Haha. Esqueça, talvez eu tenha um mais tarde.",
  str_homestory_N21yongchi_90020401_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020401_2_dialog_content = "Oficial Vivian!",
  str_homestory_N21yongchi_90020401_3_dialog_content = "Você parece preocupado com alguma coisa. Posso ser de alguma ajuda?",
  str_homestory_N21yongchi_90020401_4_dialog_content = "Uau, como você poderia dizer?",
  str_homestory_N21yongchi_90020401_5_dialog_content = "Impressionante cenestita de fato, capaz de sentir a mais leve emoção dos outros.",
  str_homestory_N21yongchi_90020401_6_dialog_content = "Haha. Talvez a forma como suas sobrancelhas estão todas franzidas tenha ajudado.",
  str_homestory_N21yongchi_90020401_7_dialog_content = "Deixe-me adivinhar. O oficial Philyshy está desaparecido de novo?",
  str_homestory_N21yongchi_90020401_8_dialog_content = "Sim, e ela está atrasada com um importante relatório de inteligência.",
  str_homestory_N21yongchi_90020401_9_dialog_content = "Ninguém pode encontrá-la em lugar nenhum.",
  str_homestory_N21yongchi_90020401_10_dialog_content = "Ela é uma verdadeira dor de cabeça.",
  str_homestory_N21yongchi_90020401_11_dialog_content = "(Philyshy tem tirado cochilos ultimamente... talvez ela esteja perto da água?)",
  str_homestory_N21yongchi_90020401_12_dialog_content = "Acho que tenho uma ideia de onde ela pode estar.",
  str_homestory_N21yongchi_90020401_13_dialog_content = "Seriamente? Seria uma grande ajuda se você pudesse encontrá-la.",
  str_homestory_N21yongchi_90020401_14_dialog_content = "Espere enquanto eu vou procurá-la.",
  str_homestory_N21yongchi_90020401_15_dialog_content = "Ah, obrigado, PlayerName!",
  str_homestory_N21yongchi_90020402_1_dialog_content = "Ei! Pomba!",
  str_homestory_N21yongchi_90020402_2_dialog_content = "Aaaaaaaaaaa—",
  str_homestory_N21yongchi_90020402_3_dialog_content = "Quem é esse? Quem está fazendo tal raquete?",
  str_homestory_N21yongchi_90020402_4_dialog_content = "PlayerName, é você?",
  str_homestory_N21yongchi_90020402_5_dialog_content = "Por que você está relaxando aqui, Dove?",
  str_homestory_N21yongchi_90020402_6_dialog_content = "S-Afrouxando? Eu não sou!",
  str_homestory_N21yongchi_90020402_7_dialog_content = "Eu só queria tirar uma soneca porque tenho trabalhado muito. E então você me deu um susto.",
  str_homestory_N21yongchi_90020402_8_dialog_content = "Oh? Então você terminou de entregar todos os seus e-mails?",
  str_homestory_N21yongchi_90020402_9_dialog_content = "Oh, os e-mails... Eu vou direto para isso, assim que eu recuperar meu sono.",
  str_homestory_N21yongchi_90020402_10_dialog_content = "E o que você está fazendo de qualquer maneira? Você não pode perturbar meu sono assim sem se explicar.",
  str_homestory_N21yongchi_90020402_11_dialog_content = "Oh sim. Me desculpe por isso. Na verdade, eu estava procurando por Philyshy.",
  str_homestory_N21yongchi_90020402_12_dialog_content = "Aqui, tem um voucher para um sorvete como um pedido de desculpas. Se estiver perto da piscina, pode experimentar um dos novos sabores da Vice.",
  str_homestory_N21yongchi_90020402_13_dialog_content = "OK. Acho que vou te perdoar então. Mas não sei onde está Philyshy.",
  str_homestory_N21yongchi_90020402_14_dialog_content = "De qualquer forma, eu estaria mais propenso a visitar se a piscina tivesse um lugar para dormir. Isso é mais importante do que sorvete, eu acho.",
  str_homestory_N21yongchi_90020402_15_dialog_content = "Talvez uma espreguiçadeira sob um guarda-sol?",
  str_homestory_N21yongchi_90020402_16_dialog_content = "Apenas o essencial para que nós, trabalhadores, possamos relaxar adequadamente.",
  str_homestory_N21yongchi_90020402_17_dialog_content = "Você tem razão. Deixe-me pensar.",
  str_homestory_N21yongchi_90020402_18_dialog_content = "Um lugar para relaxar... para relaxar... Philyshy... Entendi!",
  str_homestory_N21yongchi_90020402_19_dialog_content = "Não se esqueça de visitar o parque aquático, Dove!",
  str_homestory_N21yongchi_90020402_20_dialog_content = "Huh? OK, claro.",
  str_homestory_N21yongchi_90020403_1_dialog_content = "PlayerName, o que você está fazendo?",
  str_homestory_N21yongchi_90020403_2_dialog_content = "Estou prestes a fazer algumas espreguiçadeiras de madeira.",
  str_homestory_N21yongchi_90020403_3_dialog_content = "O que você acha? Eles são bons, certo?",
  str_homestory_N21yongchi_90020403_4_dialog_content = "Sim. Eu sabia sobre suas habilidades de comando no campo de batalha, mas... Parece que você ainda tem algumas surpresas escondidas.",
  str_homestory_N21yongchi_90020403_5_dialog_content = "Agora, quem vem visitar o parque aquático pode descansar quando quiser.",
  str_homestory_N21yongchi_90020403_6_dialog_content = "Este parque aquático está cada vez mais confortável.",
  str_homestory_N21yongchi_90020403_7_dialog_content = "Sim. Agora as pessoas podem ter um lugar para se deitar se ficarem cansadas de nadar ou se quiserem tomar um sorvete.",
  str_homestory_N21yongchi_90020403_8_dialog_content = "E essa não é a melhor parte. Estas espreguiçadeiras têm um poder secreto.",
  str_homestory_N21yongchi_90020403_9_dialog_content = "Um poder secreto?",
  str_homestory_N21yongchi_90020403_10_dialog_content = "Uma vez que eu os tenha feito e configurado, você poderá ver os resultados!",
  str_homestory_N21yongchi_90020404_1_dialog_content = "Ok, isso está tudo limpo agora.",
  str_homestory_N21yongchi_90020404_2_dialog_content = "Agora tudo que eu preciso fazer é colocar as espreguiçadeiras e esperar que a mágica aconteça.",
  str_homestory_N21yongchi_90020404_3_dialog_content = "E devo aproveitar a oportunidade para chamar a agente Vivian.",
  str_homestory_N21yongchi_90020405_1_dialog_content = "Zzzz... Zzzz... miau.",
  str_homestory_N21yongchi_90020405_2_dialog_content = "Funcionou! Seguir as pegadas levou a Philyshy!",
  str_homestory_N21yongchi_90020405_3_dialog_content = "Por que você parece dormindo mesmo quando está de pé?",
  str_homestory_N21yongchi_90020405_4_dialog_content = "Huh? Acalme-se, PlayerName. Acabei de acordar.",
  str_homestory_N21yongchi_90020405_5_dialog_content = "Bem, é melhor você parar de dormir.",
  str_homestory_N21yongchi_90020405_6_dialog_content = "Alguém está procurando por você.",
  str_homestory_N21yongchi_90020405_7_dialog_content = "Q-Quem miou? Estou acordado há apenas cinco minutos. Preciso...",
  str_homestory_N21yongchi_90020405_8_dialog_content = "Phi—ly—tímido—!",
  str_homestory_N21yongchi_90020405_9_dialog_content = "Miau?!",
  str_homestory_N21yongchi_90020405_10_dialog_content = "O-Oficial Vivian?",
  str_homestory_N21yongchi_90020405_11_dialog_content = "P-Por que você está aqui miau?",
  str_homestory_N21yongchi_90020405_12_dialog_content = "Por que você não entregou as informações que eu pedi?",
  str_homestory_N21yongchi_90020405_13_dialog_content = "E por que não consigo te encontrar em lugar nenhum? Você não estaria me evitando, estaria?",
  str_homestory_N21yongchi_90020405_14_dialog_content = "A-Evitando você? Como se eu fosse...",
  str_homestory_N21yongchi_90020405_15_dialog_content = "L-Deixe-me explicar miau...",
  str_homestory_N21yongchi_90020405_16_dialog_content = "Ok, você pode fazer isso no nosso caminho de volta.",
  str_homestory_N21yongchi_90020405_17_dialog_content = "E não se preocupe se você não puder explicar completamente agora. Eu tenho muito tempo esta noite para ouvir uma explicação completa e abrangente.",
  str_homestory_N21yongchi_90020405_18_dialog_content = "Oh miau. Você com certeza parece aterrorizante, policial Vivian.",
  str_homestory_N21yongchi_90020405_19_dialog_content = "Isso tudo por causa PlayerName e aquela linda espreguiçadeira.",
  str_homestory_N21yongchi_90020405_20_dialog_content = "Eu vou com você como ordenado miau.",
  str_homestory_N21yongchi_90020405_21_dialog_content = "PlayerName, esse é o poder secreto que você mencionou?",
  str_homestory_N21yongchi_90020405_22_dialog_content = "Uma armadilha Philyshy... muito inteligente.",
  str_homestory_N21yongchi_90020405_23_dialog_content = "Claro que sim. Eu imaginei que ela provavelmente estava deliberadamente se escondendo de todos, mas ela não seria capaz de resistir a um lugar de descanso confortável.",
  str_homestory_N21yongchi_90020405_24_dialog_content = "E com certeza, ela apareceu.",
  str_homestory_N21yongchi_90020405_25_dialog_content = "Agora tenho certeza que as espreguiçadeiras são confortáveis.",
  str_homestory_N21yongchi_90020501_1_dialog_content = "PlayerName!",
  str_homestory_N21yongchi_90020501_2_dialog_content = "Com o que você está tão preocupado?",
  str_homestory_N21yongchi_90020501_3_dialog_content = "O parque aquático parece lindo. Algo mais está incomodando você?",
  str_homestory_N21yongchi_90020501_4_dialog_content = "Bem... eu quero torná-lo ainda melhor, para que ainda mais pessoas possam apreciá-lo.",
  str_homestory_N21yongchi_90020501_5_dialog_content = "Eu tentei adicionar algumas plantas à água para tornar o ar mais fresco.",
  str_homestory_N21yongchi_90020501_6_dialog_content = "E também abrindo mais algumas barracas de lanches.",
  str_homestory_N21yongchi_90020501_7_dialog_content = "Já até pensei em ter bolsas cegas para vender como o Jomu faz.",
  str_homestory_N21yongchi_90020501_8_dialog_content = "Oh, sacos cegos... Eu não faria isso.",
  str_homestory_N21yongchi_90020501_9_dialog_content = "E tem mais alguma coisa que você gostaria de melhorar?",
  str_homestory_N21yongchi_90020501_10_dialog_content = "Não tenho certeza. Eu continuo pensando que está faltando alguma coisa quando comparo com minhas memórias da Esmeralda.",
  str_homestory_N21yongchi_90020501_11_dialog_content = "Talvez não seja tão... animado?",
  str_homestory_N21yongchi_90020501_12_dialog_content = "Parece um pouco triste.",
  str_homestory_N21yongchi_90020501_13_dialog_content = "Talvez você precise de alguém como Rainbow, um anfitrião para deixar todo mundo animado.",
  str_homestory_N21yongchi_90020501_14_dialog_content = "As pessoas vão se animar se tivermos alguém que possa criar uma atmosfera feliz.",
  str_homestory_N21yongchi_90020501_15_dialog_content = "Isso faz sentido.",
  str_homestory_N21yongchi_90020501_16_dialog_content = "Mas não posso ficar na piscina fazendo isso o tempo todo.",
  str_homestory_N21yongchi_90020501_17_dialog_content = "Deixe-me pensar. Como criar uma atmosfera?",
  str_homestory_N21yongchi_90020501_18_dialog_content = "Que tal um pouco de música? Muitos lugares diferentes usam música para criar a atmosfera apropriada.",
  str_homestory_N21yongchi_90020501_19_dialog_content = "Em Umbraton, algumas lojas tocam música clássica para ajudar os clientes a se sentirem relaxados e em casa.",
  str_homestory_N21yongchi_90020501_20_dialog_content = "E isso significa que eles gastam mais.",
  str_homestory_N21yongchi_90020501_21_dialog_content = "Mas onde vou encontrar o equipamento?",
  str_homestory_N21yongchi_90020501_22_dialog_content = "Acho que me lembro da música do Emerald.",
  str_homestory_N21yongchi_90020501_23_dialog_content = "Sim você está certo. Eles jogaram entre as competições.",
  str_homestory_N21yongchi_90020501_24_dialog_content = "Então eu deveria ir e perguntar a Rainbow novamente.",
  str_homestory_N21yongchi_90020502_1_dialog_content = "Rainbow!",
  str_homestory_N21yongchi_90020502_2_dialog_content = "PlayerName, você está todo suado novamente. Qual é a pressa?",
  str_homestory_N21yongchi_90020502_3_dialog_content = "Eu lhe disse para não se apressar tanto. Eu não vou a lugar nenhum de qualquer maneira.",
  str_homestory_N21yongchi_90020502_4_dialog_content = "Todos gostaram dos presentes que eu te dei?",
  str_homestory_N21yongchi_90020502_5_dialog_content = "Sim! Obrigado, Rainbow. E Jeno também.",
  str_homestory_N21yongchi_90020502_6_dialog_content = "Muitos aurorianos que não sabem nadar podem aproveitar o parque aquático, graças a vocês dois.",
  str_homestory_N21yongchi_90020502_7_dialog_content = "Heheh. Parece que os Aurorianos têm uma afinidade natural pela água.",
  str_homestory_N21yongchi_90020502_8_dialog_content = "Quem resiste a uma boa bóia relaxante?",
  str_homestory_N21yongchi_90020502_9_dialog_content = "Bem, contanto que você goste deles. Então, o que é desta vez?",
  str_homestory_N21yongchi_90020502_10_dialog_content = "Bem... eu gostaria de poder tocar música no parque aquático.",
  str_homestory_N21yongchi_90020502_11_dialog_content = "Oh. Isso não será barato.",
  str_homestory_N21yongchi_90020502_12_dialog_content = "E não é algo que eu possa decidir por mim mesma. Você deveria falar com Jeno.",
  str_homestory_N21yongchi_90020502_13_dialog_content = "Ele não é apenas um pintor afiado, você sabe. Ele também tem muitas ideias sobre música.",
  str_homestory_N21yongchi_90020502_14_dialog_content = "Ele é um homem muito culto, para um marinheiro.",
  str_homestory_N21yongchi_90020502_15_dialog_content = "Haha. Obrigado, Rainbow.",
  str_homestory_N21yongchi_90020502_16_dialog_content = "Eu vou falar com ele.",
  str_homestory_N21yongchi_90020503_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020503_2_dialog_content = "Como é que fico com uma sensação estranha no estômago quando te vejo?",
  str_homestory_N21yongchi_90020503_3_dialog_content = "Talvez... tenha algo a ver com aquele sorvete?",
  str_homestory_N21yongchi_90020503_4_dialog_content = "Eu penso que sim. Não me lembro do sabor, mas a memória dessa experiência ainda é muito clara.",
  str_homestory_N21yongchi_90020503_5_dialog_content = "Embora pareça ser meu estômago que se lembra disso, não eu.",
  str_homestory_N21yongchi_90020503_6_dialog_content = "É bizarro. Muito estranho mesmo.",
  str_homestory_N21yongchi_90020503_7_dialog_content = "Bem, se você quiser um pouco mais, é sempre bem-vindo ao Cloud Gardens Water Park.",
  str_homestory_N21yongchi_90020503_8_dialog_content = "Obrigada. Mas eu tento evitar alimentos açucarados.",
  str_homestory_N21yongchi_90020503_9_dialog_content = "Se eu engordasse, não teria a flexibilidade que preciso para meus shows de mágica.",
  str_homestory_N21yongchi_90020503_10_dialog_content = "Ah, mas era doce? Por que meu cérebro fica confuso sempre que tento lembrar desse sabor?",
  str_homestory_N21yongchi_90020503_11_dialog_content = "Ok, claro, er, vamos discutir o sorvete outra hora.",
  str_homestory_N21yongchi_90020503_12_dialog_content = "Preciso de um favor, Jeno. Onde posso comprar alguns equipamentos de música?",
  str_homestory_N21yongchi_90020503_13_dialog_content = "Oh, eu vejo. Você quer tocar música no parque aquático e criar uma atmosfera melhor, certo?",
  str_homestory_N21yongchi_90020503_14_dialog_content = "Eu deveria saber que você acertaria, Jeno.",
  str_homestory_N21yongchi_90020503_15_dialog_content = "Claro. E é uma coincidência engraçada...",
  str_homestory_N21yongchi_90020503_16_dialog_content = "Acontece que eu tenho alguns equipamentos antigos que eu poderia vender para você.",
  str_homestory_N21yongchi_90020503_17_dialog_content = "Ah, obrigado—",
  str_homestory_N21yongchi_90020503_18_dialog_content = "Por 50 milhões de Nightiums.",
  str_homestory_N21yongchi_90020503_19_dialog_content = "Quê?!",
  str_homestory_N21yongchi_90020503_20_dialog_content = "Isso é demais.",
  str_homestory_N21yongchi_90020503_21_dialog_content = "De jeito nenhum. Estamos falando de um deck de DJ colecionável muito raro. Paguei o dobro disso quando comprei.",
  str_homestory_N21yongchi_90020503_22_dialog_content = "Mas como somos amigos, não seria certo vender a você o lendário Suffering Knight DJ Deck.",
  str_homestory_N21yongchi_90020503_23_dialog_content = "E não é algo que eu gostaria de colocar um valor monetário.",
  str_homestory_N21yongchi_90020503_24_dialog_content = "Mas eu preciso que você prove que você é digno disso.",
  str_homestory_N21yongchi_90020503_25_dialog_content = "Passei incontáveis dias felizes com ele. Você tem que me mostrar que vai cuidar dele.",
  str_homestory_N21yongchi_90020503_26_dialog_content = "(Ah, entendi. Jeno é na verdade uma pessoa muito nostálgica.)",
  str_homestory_N21yongchi_90020503_27_dialog_content = "Então, me mostre o quanto você quer!",
  str_homestory_N21yongchi_90020503_28_dialog_content = "Trazendo-me os peixes mais raros e valiosos que se podem encontrar nestas paragens.",
  str_homestory_N21yongchi_90020503_29_dialog_content = "Eu vou!",
  str_homestory_N21yongchi_90020504_1_dialog_content = "Você conseguiu eles?",
  str_homestory_N21yongchi_90020504_2_dialog_content = "Eu fiz!({1}/{2})",
  str_homestory_N21yongchi_90020504_3_dialog_content = "Eu não achei que você seria capaz.",
  str_homestory_N21yongchi_90020504_4_dialog_content = "Mas guarde-os. Eu nunca realmente os quis.",
  str_homestory_N21yongchi_90020504_5_dialog_content = "Eu só queria ver o quão determinado você era. Quão duro você trabalharia.",
  str_homestory_N21yongchi_90020504_6_dialog_content = "Então, eu passei no teste?",
  str_homestory_N21yongchi_90020504_7_dialog_content = "É claro. O deck de DJ é seu.",
  str_homestory_N21yongchi_90020504_8_dialog_content = "E tenho certeza de que seus belos tons lhe trarão uma maior compreensão da verdade deste mundo.",
  str_homestory_N21yongchi_90020504_9_dialog_content = "Por favor, cuide bem dele.",
  str_homestory_N21yongchi_90020504_10_dialog_content = "Claro, Jeno! Eu vou.",
  str_homestory_N21yongchi_90020504_11_dialog_content = "Almost there!",
  str_homestory_N21yongchi_90020504_12_dialog_content = "Bom. Prove para mim.",
  str_homestory_N21yongchi_90020505_1_dialog_content = "Sim! Agora, limpamos um espaço e podemos configurar o Suffering Knight DJ Deck.",
  str_homestory_N21yongchi_90020505_2_dialog_content = "Embora... como isso realmente funciona?",
  str_homestory_N21yongchi_90020601_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020601_2_dialog_content = "...",
  str_homestory_N21yongchi_90020601_3_dialog_content = "PlayerName!",
  str_homestory_N21yongchi_90020601_4_dialog_content = "...",
  str_homestory_N21yongchi_90020601_5_dialog_content = "Maldito celestita!",
  str_homestory_N21yongchi_90020601_6_dialog_content = "Huh? Que?",
  str_homestory_N21yongchi_90020601_7_dialog_content = "Fia, é você!",
  str_homestory_N21yongchi_90020601_8_dialog_content = "Você estava a quilômetros de distância. O que está em sua mente?",
  str_homestory_N21yongchi_90020601_9_dialog_content = "Você continuou me ignorando. Um extrozoologista como eu merece mais respeito.",
  str_homestory_N21yongchi_90020601_10_dialog_content = "Desculpe, desculpe!",
  str_homestory_N21yongchi_90020601_11_dialog_content = "Eu estava sonhando acordado, imaginando muitas pessoas curtindo o parque aquático.",
  str_homestory_N21yongchi_90020601_12_dialog_content = "Tch. Eu vou te perdoar, eu acho.",
  str_homestory_N21yongchi_90020601_13_dialog_content = "E, er... Na verdade, eu adoraria entrar e aproveitar a piscina.",
  str_homestory_N21yongchi_90020601_14_dialog_content = "Oh? Entre. É grátis.",
  str_homestory_N21yongchi_90020601_15_dialog_content = "Eu não estava preocupado com o preço!",
  str_homestory_N21yongchi_90020601_16_dialog_content = "H-Você esqueceu?",
  str_homestory_N21yongchi_90020601_17_dialog_content = "Eu não sou... Bem, eu não sou o melhor nadador.",
  str_homestory_N21yongchi_90020601_18_dialog_content = "Oh sim. Eu me lembro agora.",
  str_homestory_N21yongchi_90020601_19_dialog_content = "Por que não tentar com um anel de natação?",
  str_homestory_N21yongchi_90020601_20_dialog_content = "Huh. Esses são para crianças. Eu não quero um desses!",
  str_homestory_N21yongchi_90020601_21_dialog_content = "Então só há uma opção.",
  str_homestory_N21yongchi_90020601_22_dialog_content = "Se você não quiser usar um anel de natação, terá que aprender a nadar.",
  str_homestory_N21yongchi_90020601_23_dialog_content = "Exatamente. Por isso vim falar com você, PlayerName.",
  str_homestory_N21yongchi_90020601_24_dialog_content = "Estou oferecendo uma boa chance de deixar você me ajudar, a grande beleza extrozoóloga, você sabe.",
  str_homestory_N21yongchi_90020601_25_dialog_content = "Não perca!",
  str_homestory_N21yongchi_90020601_26_dialog_content = "Mas... preciso dar as boas-vindas a todos, manter os vestiários arrumados, limpar o chão e a piscina.",
  str_homestory_N21yongchi_90020601_27_dialog_content = "Receio não ter tempo para te ensinar, Fia.",
  str_homestory_N21yongchi_90020601_28_dialog_content = "Oh... V-você está me rejeitando?",
  str_homestory_N21yongchi_90020601_29_dialog_content = "Não, não, como eu poderia fazer isso?",
  str_homestory_N21yongchi_90020601_30_dialog_content = "Que tal agora? Vou pedir a Vice para te ensinar.",
  str_homestory_N21yongchi_90020601_31_dialog_content = "Ela é uma nadadora muito melhor do que eu.",
  str_homestory_N21yongchi_90020601_32_dialog_content = "Hum. Vício?",
  str_homestory_N21yongchi_90020601_33_dialog_content = "Está bem então. Eu posso ver que você tem muito trabalho, PlayerName.",
  str_homestory_N21yongchi_90020601_34_dialog_content = "Então não seria educado da minha parte insistir.",
  str_homestory_N21yongchi_90020601_35_dialog_content = "Aqui estão alguns pequenos presentes como agradecimento.",
  str_homestory_N21yongchi_90020601_36_dialog_content = "Obrigado, Fia!",
  str_homestory_N21yongchi_90020601_37_dialog_content = "Sim! Assim que eu aprender, podemos ir nadar juntos.",
  str_homestory_N21yongchi_90020601_38_dialog_content = "OK. Vou encontrar Vice.",
  str_homestory_N21yongchi_90020601_39_dialog_content = "Claro. Eu espero aqui por você.",
  str_homestory_N21yongchi_90020602_1_dialog_content = "Hum. Aquele tapete inflável...",
  str_homestory_N21yongchi_90020602_2_dialog_content = "É muito o estilo da Fia.",
  str_homestory_N21yongchi_90020602_3_dialog_content = "Acho que deveria mover um pouco a cadeira inflável.",
  str_homestory_N21yongchi_90020602_4_dialog_content = "Vou guardá-los por enquanto para o caso de algum dos visitantes esbarrar neles.",
  str_homestory_N21yongchi_90020603_1_dialog_content = "Vício? O que você está fazendo na Torre Branca? Eu estou olhando para você.",
  str_homestory_N21yongchi_90020603_2_dialog_content = "Hum! PlayerName! Estou procurando você também.",
  str_homestory_N21yongchi_90020603_3_dialog_content = "O que houve?",
  str_homestory_N21yongchi_90020603_4_dialog_content = "<color=#e8d9bb>Toc, toc!</color>",
  str_homestory_N21yongchi_90020603_5_dialog_content = "É meio constrangedor... Parece que a máquina de sorvete está quebrada.",
  str_homestory_N21yongchi_90020603_6_dialog_content = "Quebrado?",
  str_homestory_N21yongchi_90020603_7_dialog_content = "Eu não tenho certeza.",
  str_homestory_N21yongchi_90020603_8_dialog_content = "Simplesmente parou. E eu estava gostando muito de fazer todos os meus novos sabores de sorvete.",
  str_homestory_N21yongchi_90020603_9_dialog_content = "Ahh! Vamos! Como podemos salvá-lo? Não prometemos que daríamos a todos um ótimo verão?",
  str_homestory_N21yongchi_90020603_10_dialog_content = "Parece que você e a máquina de sorvete se tornaram amigos íntimos.",
  str_homestory_N21yongchi_90020603_11_dialog_content = "É claro! Estamos trabalhando lado a lado há 20 horas, sem parar.",
  str_homestory_N21yongchi_90020603_12_dialog_content = "20 horas! Vice, você precisa fazer uma pausa.",
  str_homestory_N21yongchi_90020603_13_dialog_content = "E suspeito que o problema com a máquina possa estar relacionado ao excesso de trabalho.",
  str_homestory_N21yongchi_90020603_14_dialog_content = "Hmmm. Eu posso ter esquecido essa possibilidade.",
  str_homestory_N21yongchi_90020603_15_dialog_content = "Talvez seja minha culpa que quebrou... E depois de tanto trabalho para conseguir. Desculpe, PlayerName.",
  str_homestory_N21yongchi_90020603_16_dialog_content = "Eu estava planejando um sabor absolutamente alucinante para você se deliciar.",
  str_homestory_N21yongchi_90020603_17_dialog_content = "Bem, é o pensamento que conta.",
  str_homestory_N21yongchi_90020603_18_dialog_content = "Estava agindo estranho antes de parar de funcionar?",
  str_homestory_N21yongchi_90020603_19_dialog_content = "Deixe-me pensar. Acho que pode ter havido uma luz vermelha piscando.",
  str_homestory_N21yongchi_90020603_20_dialog_content = "Então, talvez não estivesse recebendo energia suficiente?",
  str_homestory_N21yongchi_90020603_21_dialog_content = "Se você se lembra das fotos acima. Há uma árvore e uma pedra.",
  str_homestory_N21yongchi_90020603_22_dialog_content = "Talvez pudéssemos alimentá-lo com madeira e minério e ver o que acontece?",
  str_homestory_N21yongchi_90020603_23_dialog_content = "Embora eu não veja por que uma máquina de sorvete funcionaria com madeira e minério.",
  str_homestory_N21yongchi_90020603_24_dialog_content = "Eu vou pegar um pouco de qualquer maneira. Veremos o que acontece.",
  str_homestory_N21yongchi_90020604_1_dialog_content = "Você conseguiu a madeira?",
  str_homestory_N21yongchi_90020604_2_dialog_content = "Claro que sim.({1}/{2})",
  str_homestory_N21yongchi_90020604_3_dialog_content = "Obrigado! Agora vá e encontre algum minério.",
  str_homestory_N21yongchi_90020604_4_dialog_content = "Vai fazer.",
  str_homestory_N21yongchi_90020604_5_dialog_content = "Não o suficiente.",
  str_homestory_N21yongchi_90020604_6_dialog_content = "Boa sorte! Eu estarei aqui mesmo.",
  str_homestory_N21yongchi_90020605_1_dialog_content = "Você tem o minério também?",
  str_homestory_N21yongchi_90020605_2_dialog_content = "Isso.({1}/{2})",
  str_homestory_N21yongchi_90020605_3_dialog_content = "Você é sempre tão rápido, PlayerName.",
  str_homestory_N21yongchi_90020605_4_dialog_content = "Vamos ver se funciona.",
  str_homestory_N21yongchi_90020605_5_dialog_content = "Pronto, coloquei tudo.",
  str_homestory_N21yongchi_90020605_6_dialog_content = "Nada vai mudar se não tentarmos. Aqui, eu vou fazer isso.",
  str_homestory_N21yongchi_90020605_7_dialog_content = "<color=#e8d9bb>Crocante crocante.</color>",
  str_homestory_N21yongchi_90020605_8_dialog_content = "<color=#e8d9bb>Crocante crocante.</color>",
  str_homestory_N21yongchi_90020605_9_dialog_content = "Eu espero que isso funcione.",
  str_homestory_N21yongchi_90020605_10_dialog_content = "Tudo o que podemos fazer agora é orar.",
  str_homestory_N21yongchi_90020605_11_dialog_content = "Crocante crocante.",
  str_homestory_N21yongchi_90020605_12_dialog_content = "É... Vice...",
  str_homestory_N21yongchi_90020605_13_dialog_content = "Eu só quero perguntar... Você não maltratou a máquina de sorvete, não é?",
  str_homestory_N21yongchi_90020605_14_dialog_content = "Haha. Como se eu fosse fazer isso.",
  str_homestory_N21yongchi_90020605_15_dialog_content = "Crocante crocante.",
  str_homestory_N21yongchi_90020605_16_dialog_content = "Crunch crunch crunch crunch.",
  str_homestory_N21yongchi_90020605_17_dialog_content = "Como alimentá-lo com ingredientes estranhos, talvez?",
  str_homestory_N21yongchi_90020605_18_dialog_content = "Hum. Eu não acho. A menos que conchas, ossos e um peixe inteiro sejam estranhos.",
  str_homestory_N21yongchi_90020605_19_dialog_content = "Você fez o que!?",
  str_homestory_N21yongchi_90020605_20_dialog_content = "E... Bem, se a ingestão de ingredientes emperrou, eu poderia ter dado um bom baque.",
  str_homestory_N21yongchi_90020605_21_dialog_content = "Mas um baque muito preciso, eu prometo!",
  str_homestory_N21yongchi_90020605_22_dialog_content = "Perfeitamente adaptado ao problema. E não causou nenhum dano!",
  str_homestory_N21yongchi_90020605_23_dialog_content = "Eu sabia. Você deveria tentar ser um pouco mais gentil com isso.",
  str_homestory_N21yongchi_90020605_24_dialog_content = "Espero que seja apenas ficar sem energia. Caso contrário, não sei como vamos corrigi-lo.",
  str_homestory_N21yongchi_90020605_25_dialog_content = "Eu sei. Eu serei mais cuidadoso.",
  str_homestory_N21yongchi_90020605_26_dialog_content = "PlayerName, isso é incrível!",
  str_homestory_N21yongchi_90020605_27_dialog_content = "Ainda não entendi COMO funciona. Mas estou feliz que sim!",
  str_homestory_N21yongchi_90020605_28_dialog_content = "Excelente. A máquina de sorvete voltou a funcionar.",
  str_homestory_N21yongchi_90020605_29_dialog_content = "Ah, quase esqueci por que vim.",
  str_homestory_N21yongchi_90020605_30_dialog_content = "É assim: Fia quer aprender a nadar, e eu sei que você é um nadador forte.",
  str_homestory_N21yongchi_90020605_31_dialog_content = "Então, talvez você possa ensiná-la, quando tiver tempo?",
  str_homestory_N21yongchi_90020605_32_dialog_content = "O que, isso é tudo?",
  str_homestory_N21yongchi_90020605_33_dialog_content = "Deixe-me pegar isso e consertar a máquina de sorvete, e depois irei ver Fia.",
  str_homestory_N21yongchi_90020605_34_dialog_content = "Diga a ela para esperar por mim na piscina. Vou mostrar a ela alguns dos melhores métodos de treinamento da Illumina.",
  str_homestory_N21yongchi_90020605_35_dialog_content = "Fia vai derrubá-lo desta vez. Isso será algo para comemorar!",
  str_homestory_N21yongchi_90020605_36_dialog_content = "Estará certo.",
  str_homestory_N21yongchi_90020605_37_dialog_content = "Só mais um pouco, vamos!",
  str_homestory_N21yongchi_90020606_1_dialog_content = "Puff... Estou exausto.",
  str_homestory_N21yongchi_90020606_2_dialog_content = "PlayerName, você parece muito ocupado.",
  str_homestory_N21yongchi_90020606_3_dialog_content = "Deve ser cansativo administrar um lugar tão grande.",
  str_homestory_N21yongchi_90020606_4_dialog_content = "Claro que é. Eu preciso cuidar de muitas coisas diferentes aqui.",
  str_homestory_N21yongchi_90020606_5_dialog_content = "Mas estou feliz por ter criado um lugar onde todos podem se divertir.",
  str_homestory_N21yongchi_90020606_6_dialog_content = "Isso é verdade, mas você não tem tempo para relaxar e se divertir, não é?",
  str_homestory_N21yongchi_90020606_7_dialog_content = "Heh. Não, isso é verdade.",
  str_homestory_N21yongchi_90020606_8_dialog_content = "Ultimamente tenho trabalhado do amanhecer ao anoitecer.",
  str_homestory_N21yongchi_90020606_9_dialog_content = "Sim. Assim como Vice e eu pensamos.",
  str_homestory_N21yongchi_90020606_10_dialog_content = "Por isso viemos ajudar.",
  str_homestory_N21yongchi_90020606_11_dialog_content = "Vamos assumir a gestão do parque aquático por um tempo.",
  str_homestory_N21yongchi_90020606_12_dialog_content = "Então você vai poder aproveitar também.",
  str_homestory_N21yongchi_90020606_13_dialog_content = "Seriamente?",
  str_homestory_N21yongchi_90020606_14_dialog_content = "É claro. Você merece isso.",
  str_homestory_N21yongchi_90020606_15_dialog_content = "Quero dizer, nem sempre podemos nos beneficiar de todo o seu trabalho duro, podemos?",
  str_homestory_N21yongchi_90020606_16_dialog_content = "Incrível. Eu esperava fazer isso!",
  str_homestory_N21yongchi_90020606_17_dialog_content = "Agora vou me divertir do amanhecer ao anoitecer.",
  str_homestory_N21yongchi_90020606_18_dialog_content = "Vou nadar 300 voltas na piscina.",
